package com.bank.content.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Generates all unique generalized abbreviations of a word.
public class AbbreviationService {
    private static final Logger log = Logger.getLogger(AbbreviationService.class.getName());

    public List<String> allAbbreviations(String word) {
        List<String> result = new ArrayList<>();
        backtrack(word, 0, 0, new StringBuilder(), result);
        log.info(() -> "Generated " + result.size() + " abbreviations for '" + word + "'");
        return result;
    }

    private void backtrack(String word, int index, int count,
                           StringBuilder current, List<String> result) {
        if (index == word.length()) {
            int len = current.length();
            if (count > 0) {
                current.append(count); // flush trailing abbreviated run
            }
            result.add(current.toString());
            log.fine(() -> "Completed abbreviation " + result.get(result.size() - 1));
            current.setLength(len); // backtrack the flushed count
            return;
        }
        // Choice 1: abbreviate this character (extend the skip count).
        backtrack(word, index + 1, count + 1, current, result);

        // Choice 2: keep this character as a literal.
        int len = current.length();
        if (count > 0) {
            current.append(count); // flush the pending count first
        }
        current.append(word.charAt(index));
        backtrack(word, index + 1, 0, current, result);
        current.setLength(len); // backtrack both the count and the char
    }
}
